INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5691550, 826817, 59276, '<td valign="top">nice abstract!</td>', 'nice abstract!', '2009-10-18 23:26:00.000000', NULL, 1),
(5691559, 827213, 103142, '<td valign="top">spectacular! I almost bought an old window from an antique store to do this same, exact shot! However, my cat doesn''t wear a collar, and your shot is much better than my imaginary shot because the collar adds a lot! wonderfully done! 9</td>', 'spectacular! I almost bought an old window from an antique store to do this same, exact shot! However, my cat doesn''t wear a collar, and your shot is much better than my imaginary shot because the collar adds a lot! wonderfully done! 9', '2009-10-18 23:37:24.000000', NULL, 1),
(5691560, 827112, 103142, '<td valign="top">ooh! Very nice!! 9</td>', 'ooh! Very nice!! 9', '2009-10-18 23:37:26.000000', NULL, 1),
(5691562, 826958, 103142, '<td valign="top">Very interesting! I really like it! 9</td>', 'Very interesting! I really like it! 9', '2009-10-18 23:37:35.000000', NULL, 1),
(5691563, 827233, 103142, '<td valign="top">I have a feeling that you''re getting hit hard for the oof, but I really like it. It makes what would have been a relatively uninteresting shot quite enigmatic and much more interesting. Well done! 8</td>', 'I have a feeling that you''re getting hit hard for the oof, but I really like it. It makes what would have been a relatively uninteresting shot quite enigmatic and much more interesting. Well done! 8', '2009-10-18 23:37:48.000000', NULL, 1),
(5691564, 827234, 90474, '<td valign="top">The blurred border on the top and left bothers me a little.</td>', 'The blurred border on the top and left bothers me a little.', '2009-10-18 23:37:50.000000', NULL, 1),
(5691565, 826949, 103142, '<td valign="top">lovely! (don''t you hate short comments?)</td>', 'lovely! (don''t you hate short comments?)', '2009-10-18 23:37:50.000000', NULL, 1),
(5691566, 827139, 103142, '<td valign="top">I''m a little nervous that you might be getting hit from people thinking that it''s not a view from a window, but a view of a window. I''m a little on the fence about meeting the challenge, but it''s such an interesting shot and I love the angle and the balcony around the corner that I say it''s close enough!! 8</td>', 'I''m a little nervous that you might be getting hit from people thinking that it''s not a view from a window, but a view of a window. I''m a little on the fence about meeting the challenge, but it''s such an interesting shot and I love the angle and the balcony around the corner that I say it''s close enough!! 8', '2009-10-18 23:37:52.000000', NULL, 1),
(5691567, 827228, 103142, '<td valign="top">very interesting and unusual take on the challenge. Nicely done! 8</td>', 'very interesting and unusual take on the challenge. Nicely done! 8', '2009-10-18 23:37:54.000000', NULL, 1),
(5691568, 827240, 103142, '<td valign="top">lovely!</td>', 'lovely!', '2009-10-18 23:37:57.000000', NULL, 1),
(5691569, 827192, 103142, '<td valign="top">love it! It feels kind of like an Alfred Hitchcock movie. Like the angle and the blur. Interesting choice! 8</td>', 'love it! It feels kind of like an Alfred Hitchcock movie. Like the angle and the blur. Interesting choice! 8', '2009-10-18 23:38:00.000000', NULL, 1),
(5691570, 827046, 103142, '<td valign="top">First of all, spectacular catch! I would have cropped off the left side since the reflection so bright and also cropped a chunk off the top since it draws the eye. (ok, so 2/3 of the way into the left panes and down 2/3 of the top panes.) It would move him a little off center and bring out the nice glowing colors since it''s not up against the overblown highlights.<br/> <br/>feel free to disagree--it was just such a great shot, I had to put my two cents in :D  8</td>', 'First of all, spectacular catch! I would have cropped off the left side since the reflection so bright and also cropped a chunk off the top since it draws the eye. (ok, so 2/3 of the way into the left panes and down 2/3 of the top panes.) It would move him a little off center and bring out the nice glowing colors since it''s not up against the overblown highlights. feel free to disagree--it was just such a great shot, I had to put my two cents in :D  8', '2009-10-18 23:38:02.000000', NULL, 1),
(5691571, 827255, 103142, '<td valign="top">Love the sheep! (Roz''s sheep?) Love the expression on the face, but don''t care for the piece of bread. (is it bread?) The face is so wonderful, but I keep getting distracted wondering if it''s bread and why sheep would like bread... :D -7-</td>', 'Love the sheep! (Roz''s sheep?) Love the expression on the face, but don''t care for the piece of bread. (is it bread?) The face is so wonderful, but I keep getting distracted wondering if it''s bread and why sheep would like bread... :D -7-', '2009-10-18 23:38:04.000000', NULL, 1),
(5691572, 826994, 103142, '<td valign="top">My first thought was, wow, really cool! But the more you look at it, there''s nothing very interesting going on in the red. I like the color and the lines, but it''s not enough to carry all that empty red space, imo. Still a very nice photo, but went from an 8 to a 7 as you looked for awhile.</td>', 'My first thought was, wow, really cool! But the more you look at it, there''s nothing very interesting going on in the red. I like the color and the lines, but it''s not enough to carry all that empty red space, imo. Still a very nice photo, but went from an 8 to a 7 as you looked for awhile.', '2009-10-18 23:38:09.000000', NULL, 1),
(5691573, 827250, 103142, '<td valign="top">I was just thinking a 6, but your title was truly inspired, it really enhanced the enjoyment of the photo. 7</td>', 'I was just thinking a 6, but your title was truly inspired, it really enhanced the enjoyment of the photo. 7', '2009-10-18 23:38:12.000000', NULL, 1),
(5691574, 827218, 103142, '<td valign="top">wow, what a funny looking dog!! Is this a bus? I would have cropped out about half of the dash. You were probably going more for thirds, but there''s not a lot of interest in the bottom half. But I''m finding myself really drawn to this one.  7!</td>', 'wow, what a funny looking dog!! Is this a bus? I would have cropped out about half of the dash. You were probably going more for thirds, but there''s not a lot of interest in the bottom half. But I''m finding myself really drawn to this one.  7!', '2009-10-18 23:38:14.000000', NULL, 1),
(5691575, 827186, 103142, '<td valign="top">don''t you wish it were real? lovely choice</td>', 'don''t you wish it were real? lovely choice', '2009-10-18 23:38:17.000000', NULL, 1),
(5691576, 827250, 110186, '<td valign="top">I love this picture. :)</td>', 'I love this picture. :)', '2009-10-18 23:38:17.000000', NULL, 1),
(5691577, 827021, 103142, '<td valign="top">ok, so I''m strange, but I really like this one!!</td>', 'ok, so I''m strange, but I really like this one!!', '2009-10-18 23:38:18.000000', NULL, 1),
(5691578, 827229, 103142, '<td valign="top">I like it very much, but I really wish the siding was cropped off. It is intriguing that the siding is over it and that it has fair poorly and the siding has held up. However, that is so unimportant compared to the window and the reflection. The siding is just a distraction. 7 as it is. But it could have possibly been a 9 without. Wonderful discovery!</td>', 'I like it very much, but I really wish the siding was cropped off. It is intriguing that the siding is over it and that it has fair poorly and the siding has held up. However, that is so unimportant compared to the window and the reflection. The siding is just a distraction. 7 as it is. But it could have possibly been a 9 without. Wonderful discovery!', '2009-10-18 23:38:39.000000', NULL, 1),
(5691580, 827291, 103142, '<td valign="top">Well done, it''s a hard shot to get with movement and a large depth of field. Not the most interesting photo, however, even though it''s well done. 6</td>', 'Well done, it''s a hard shot to get with movement and a large depth of field. Not the most interesting photo, however, even though it''s well done. 6', '2009-10-18 23:38:51.000000', NULL, 1),
(5691581, 826932, 103142, '<td valign="top">I like this shot quite a bit, however, it seems like the leaves are a tad overexposed.</td>', 'I like this shot quite a bit, however, it seems like the leaves are a tad overexposed.', '2009-10-18 23:38:54.000000', NULL, 1),
(5691582, 827220, 103142, '<td valign="top">I like it! innovative &amp; different. Seems a tad dark...</td>', 'I like it! innovative & different. Seems a tad dark...', '2009-10-18 23:38:55.000000', NULL, 1),
(5691583, 826835, 103142, '<td valign="top">I like this quite a bit, but it seems like too much dashboard. I''d love to see more of the shot. 6</td>', 'I like this quite a bit, but it seems like too much dashboard. I''d love to see more of the shot. 6', '2009-10-18 23:39:07.000000', NULL, 1),
(5691585, 827142, 103142, '<td valign="top">It gets more interesting as you look at it. Of course the first reaction is the reflection is extremely distracting, but then it''s actually fun exploring the reflection. It think it would have been much stronger photo if the people weren''t mugging for the camera. Makes it look just like a snapshot. If they were in their own little world, I think this could be far more interesting.</td>', 'It gets more interesting as you look at it. Of course the first reaction is the reflection is extremely distracting, but then it''s actually fun exploring the reflection. It think it would have been much stronger photo if the people weren''t mugging for the camera. Makes it look just like a snapshot. If they were in their own little world, I think this could be far more interesting.', '2009-10-18 23:39:33.000000', NULL, 1),
(5691622, 827142, 38162, '<td valign="top">we get it</td>', 'we get it', '2009-10-19 00:53:09.000000', NULL, 1),
(5691624, 827061, 38162, '<td valign="top">windy title doesnt help.</td>', 'windy title doesnt help.', '2009-10-19 00:54:14.000000', NULL, 1),
